    def list_authors_with_optional_book
      with_client('list_authors_with_optional_book') do |client|
        unless client.prepared_statements.include?('query_sql_list_authors_with_optional_book')
          client.prepare('query_sql_list_authors_with_optional_book', LIST_AUTHORS_WITH_OPTIONAL_BOOK_SQL)
          client.prepared_statements.add('query_sql_list_authors_with_optional_book')
        end
        result = client.exec_prepared('query_sql_list_authors_with_optional_book').values
        result.map do |row|
          ListAuthorsWithOptionalBookRow.new(row[0].nil? && row[1].nil? ? nil : Author.new(row[0], row[1], row[2]), row[3].nil? && row[4].nil? && row[5].nil? ? nil : Book.new(row[3], row[4], row[5], row[6]))
        end
      end
    end

    def list_authors_between_ids(id:, id_2:)
      with_client('list_authors_between_ids') do |client|
        query_params = [id, id_2]
        unless client.prepared_statements.include?('query_sql_list_authors_between_ids')
          client.prepare('query_sql_list_authors_between_ids', LIST_AUTHORS_BETWEEN_IDS_SQL)
          client.prepared_statements.add('query_sql_list_authors_between_ids')
        end
        result = client.exec_prepared('query_sql_list_authors_between_ids', query_params)
        result.map do |row|
          ListAuthorsBetweenIdsRow.new(row['id'], row['name'], row['bio'])
        end
      end
    end

    private

    def instrument(name)
      return yield unless @logger

      started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
      begin
        yield
      ensure
        elapsed = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - started) * 1000
        @logger.debug { format('%<class>s#%<name>s (%<ms>.1fms)', class: self.class.name, name: name, ms: elapsed) }
      end
    end

    def with_client(name)
      instrument(name) do
        @db.with do |client|
          configure(client) unless client.is_a?(ConnectionState)
          yield client
        end
      end
    end

    # Connections of an injected pool are set up on first use: typed results and Ruby arrays as parameters.
    def configure(client)
      type_map = PG::BasicTypeMapForResults.new(client)
      # uuid, enums, money, ... come back as Strings, arrays of them (uuid[], enum[], ...) as Arrays of Strings
      fallback = PG::TypeMapByOid.new
      client.exec("SELECT oid FROM pg_type WHERE typcategory = 'A'").each do |row|
        fallback.add_coder(PG::TextDecoder::Array.new(oid: row['oid'].to_i, elements_type: PG::TextDecoder::String.new))
      end
      fallback.default_type_map = PG::TypeMapAllStrings.new
      type_map.default_type_map = fallback
      client.type_map_for_results = type_map
      client.type_map_for_queries = PG::BasicTypeMapForQueries.new(client)
      client.extend(ConnectionState)
    end
  end
end
